import java.util.*;

class Solution {
  public List<Integer> countSteppingNumbers(int low, int high) {
    List<Integer> res = new ArrayList<>();
    if (low == 0) res.add(0);
    // BFS by length keeps the numbers in increasing order
    Deque<Long> q = new ArrayDeque<>();
    for (long d = 1; d <= 9; d++) q.add(d);
    while (!q.isEmpty()) {
      long x = q.poll();
      if (x > high) continue;
      if (x >= low) res.add((int) x);
      long last = x % 10;
      if (last > 0) q.add(x * 10 + last - 1);
      if (last < 9) q.add(x * 10 + last + 1);
    }
    return res;
  }
}
